import{_ as e,o,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2018-09-27","description":"","frontmatter":{"title":"Ceph Performance Meeting 2018-09-27","date":"2018-09-27T00:00:00.000Z","updated":"2018-10-18T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","内存管理","异步消息传递"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Performance_Meeting_2018-09-27.md","filePath":"posts/2018/Ceph_Performance_Meeting_2018-09-27.md","lastUpdated":1780460162000}'),r={name:"posts/2018/Ceph_Performance_Meeting_2018-09-27.md"};function a(s,l,n,p,g,d){return o(),i("div",null,[...l[0]||(l[0]=[t('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2018年9月27日</p><p><strong>参会人员</strong>： Sage（缺席）、Radek、Braddock、Casey、Jason、Ilya、Dr. Lyric Easy、Nelson、Josh、Reich</p><p><strong>会议主题</strong>： Ceph分布式存储项目性能讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、新特性与改进</strong></p><ol><li><p><strong>Sage缓存大小调整</strong>：</p><ul><li>Sage计划增加mon节点的缓存大小，特别是ark rocks DB缓存。</li><li>讨论了自动调整缓存大小的工作，并考虑是否应该在所有地方应用这种策略。</li><li>决定提高mon节点的缓存大小，以解决之前遇到的问题。</li></ul></li><li><p><strong>Radek的工作</strong>：</p><ul><li>Radek正在处理向后迭代、缓冲列表等问题，以降低编码宏和常量的开销。</li><li>讨论了缓冲列表中追加操作的性能问题，并考虑了优化方案。</li><li>引入了基于共享内存的计数器，以优化内存使用。</li></ul></li><li><p><strong>Braddock的工作</strong>：</p><ul><li>Braddock正在优化mempool和slab分配器，以便更好地管理内存。</li><li>讨论了在C*世界中如何应用这种优化方法。</li></ul></li><li><p><strong>C*内存模型</strong>：</p><ul><li>讨论了C*内存模型的长期方向，以及如何逐步实现。</li><li>认为采用逐步改进的策略比革命性的改变更为可行。</li></ul></li><li><p><strong>异步消息传递</strong>：</p><ul><li>讨论了异步消息传递的性能问题，并考虑了优化方案。</li><li>认为通过优化消息传递组件，可以提高整体性能。</li></ul></li></ol><p><strong>二、其他事项</strong></p><ol><li><p><strong>Exodus默认AG账户问题</strong>：</p><ul><li>讨论了Exodus默认AG账户导致性能问题的情况。</li><li>认为需要改进BD设备导出，以使i/o调度器做出更好的选择。</li></ul></li><li><p><strong>对象存储</strong>：</p><ul><li>讨论了对象存储中的性能问题，并考虑了优化方案。</li></ul></li><li><p><strong>Pet Store项目</strong>：</p><ul><li>讨论了Pet Store项目的进展，并考虑了将其迁移到主分支。</li></ul></li></ol><p><strong>三、后续行动计划</strong></p><ol><li>Radek继续优化缓冲列表和异步消息传递。</li><li>Braddock继续优化mempool和slab分配器。</li><li>Dr. Lyric Easy和Adam讨论对象存储项目。</li><li>Nelson准备下周的会议议题。</li></ol><p><strong>四、会议总结</strong></p><p>本次会议讨论了Ceph分布式存储项目的多个方面，包括新特性、改进方案和后续行动计划。参会人员积极参与讨论，并提出了许多有价值的建议。</p><h2 id="识别的潜在错误、误解或遗漏的信息" tabindex="-1">识别的潜在错误、误解或遗漏的信息 <a class="header-anchor" href="#识别的潜在错误、误解或遗漏的信息" aria-label="Permalink to &quot;识别的潜在错误、误解或遗漏的信息&quot;">​</a></h2><ol><li>原始总结中未提及Sage的缺席原因，而原始字幕中提到Sage本周缺席。</li><li>原始字幕中提到了Pet Store项目的讨论，但原始总结中未提及。</li><li>原始总结中未提及Braddock关于C*内存模型的工作，而原始字幕中有所提及。</li><li>原始总结中未提及异步消息传递的性能问题，而原始字幕中有所提及。</li></ol><h2 id="改进后的总结" tabindex="-1">改进后的总结 <a class="header-anchor" href="#改进后的总结" aria-label="Permalink to &quot;改进后的总结&quot;">​</a></h2><ol><li>在会议纪要中添加了Sage缺席的原因。</li><li>在会议纪要中添加了Pet Store项目的讨论内容。</li><li>在会议纪要中添加了Braddock关于C*内存模型的工作内容。</li><li>在会议纪要中添加了异步消息传递的性能问题讨论内容。</li></ol>',18)])])}const u=e(r,[["render",a]]);export{_ as __pageData,u as default};
